<script setup>
import { computed, ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const props=defineProps({modelValue:Boolean,challenge:Object})
const emit=defineEmits(['update:modelValue','verified'])
const open=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)})
const code=ref(''),busy=ref(false),remember=ref(true),$q=useQuasar()
watch(()=>props.challenge,()=>{code.value='';remember.value=true})
async function verify(){busy.value=true;try{const {data}=await api.post('/auth/mfa/verify',{challengeId:props.challenge?.challengeId,code:code.value,rememberDevice:remember.value});emit('verified',data);open.value=false}catch(error){$q.notify({type:'negative',message:error.response?.data?.message||'Não foi possível validar o código.'})}finally{busy.value=false}}
</script>
<template><q-dialog v-model="open" persistent><q-card class="mfa-card"><q-card-section><div class="mfa-icon"><q-icon name="mdi-email-lock-outline"/></div><h2>Confirme seu e-mail</h2><p>Enviamos um código para <strong>{{challenge?.emailMasked || 'seu e-mail'}}</strong>.</p><q-banner rounded class="mfa-note">Confira também o spam e o lixo eletrônico. O código expira em 5 minutos e pode ser usado uma única vez.</q-banner><q-form @submit.prevent="verify"><q-input v-model="code" outlined autofocus label="Código de 6 dígitos" inputmode="numeric" autocomplete="one-time-code" mask="######" class="q-mt-md" :rules="[v=>/^\d{6}$/.test(v)||'Informe os seis dígitos.']"/><q-checkbox v-model="remember" label="Manter acesso neste dispositivo por 120 dias" class="mfa-remember"/><div class="mfa-actions"><q-btn flat no-caps label="Voltar" :disable="busy" @click="open=false"/><q-btn unelevated no-caps label="Validar e entrar" color="teal-7" type="submit" :loading="busy" :disable="!/^\d{6}$/.test(code)"/></div></q-form></q-card-section></q-card></q-dialog></template>
<style scoped>.mfa-card{width:min(460px,calc(100vw - 28px));border:1px solid #9ce4d1;border-radius:22px;background:linear-gradient(145deg,#f8fffc,#eaf9f4);color:#143c32;padding:6px}.mfa-icon{display:grid;place-items:center;height:54px;width:54px;border-radius:17px;background:#d3f3e9;color:#0b886a;font-size:28px}.mfa-card h2{font-size:25px;line-height:1.3;margin:18px 0 12px;font-weight:750}.mfa-card p{font-size:14px;line-height:1.7;color:#517568;overflow-wrap:anywhere}.mfa-note{font-size:12px;line-height:1.8;background:#daf2e9;color:#346655}.mfa-remember{font-size:12px;line-height:1.6}.mfa-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:14px}.mfa-card :deep(.q-field__control){background:#ffffffa3}.mfa-card :deep(.q-field__native){font-size:22px;letter-spacing:.25em}@media(max-width:400px){.mfa-actions{flex-direction:column-reverse}.mfa-remember{font-size:11px}}</style>
